package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch77 {
    val stories = listOf(
        StorySeries(
            id = "orchard_gate_register",
            title = "The Orchard Gate Register",
            tagline = "A forgotten orchard becomes a shared classroom again.",
            parts = listOf(
                StoryPart(1, "The Old Register", listOf("When the school gardening club visited the abandoned orchard, they found a weathered register in the caretaker's shed. It listed names beside dates and small drawings of fruit trees.", "The orchard belonged to the town, but no one knew who had planted its oldest trees. The club's adviser, Mrs James, asked the students not to remove anything until the council confirmed the records could be examined.", "Tari noticed that several names matched families still living nearby.")),
                StoryPart(2, "A Family Name", listOf("Tari asked her neighbour, Mr Okorie, about his family's name in the register. He remembered his grandmother speaking about a planting day, but he had never seen a photograph.", "He offered to help contact other families. The students agreed to record memories separately from facts they could verify.", "The register showed that the first planting had happened during a school holiday decades earlier.")),
                StoryPart(3, "The Photograph Box", listOf("The local history room held photographs from town events. A volunteer found one showing children beside young trees, with a banner partly hidden behind them.", "The visible words read 'Future Orchard Project'. On the back, someone had written the name of the school gardening club's predecessor.", "Tari recognised the old school badge and asked the archivist to check its year.")),
                StoryPart(4, "The First Plan", listOf("The archive contained a simple orchard plan with rows marked by tree type. It had been drawn by a science teacher and signed by students.", "The plan showed that the orchard had been designed as an outdoor classroom. The trees were planted to support lessons about seasons, soil, and local food.", "Mrs James suggested that the club compare the plan with the trees still standing.")),
                StoryPart(5, "Trees with Stories", listOf("A horticulture volunteer helped identify the surviving trees without damaging them. Some were older varieties, while others had been replanted later.", "The register included notes about harvests and repairs. One entry thanked a family for replacing a broken water barrel after a dry season.", "Tari realised the orchard had survived because many people had cared for it over time.")),
                StoryPart(6, "The Locked Gate", listOf("The orchard gate was locked because the council had not yet completed its safety review. Some students wanted to begin clearing the paths immediately.", "Mrs James explained that enthusiasm did not replace permission or a safety assessment. They could plan, document, and request supervised access, but should not enter the closed area.", "The club wrote to the council with the old plan and offered to help once the site was approved.")),
                StoryPart(7, "A Community Meeting", listOf("The council invited residents to discuss the orchard's future. Older neighbours wanted to preserve the trees, while families asked for safe paths and accessible seating.", "The students presented the register, photographs, and planting plan. They explained which details were documented and which came from interviews.", "The council agreed to inspect the gate, paths, and trees, then publish a restoration schedule.")),
                StoryPart(8, "A Careful Restoration", listOf("After the inspection, trained workers repaired the gate and cleared unsafe sections. The club helped with approved tasks under supervision, such as labelling trees and preparing information boards.", "The horticulture volunteer advised against replacing every old tree. Some healthy trees were valuable examples of local varieties and needed careful care.", "Tari helped create labels that included common names and a note that identification could be updated if experts found new evidence.")),
                StoryPart(9, "The Orchard Open Day", listOf("The orchard reopened for a supervised community day. Families recognised names in the register and shared additional photographs with the history room.", "Children followed a short learning trail about pollination, seasons, and soil. The club displayed the original plan beside a new map of the restored site.", "Mr Okorie brought a photograph of his grandmother planting a young tree. Tari added it to the archive with his family's permission.")),
                StoryPart(10, "A Register for Tomorrow", listOf("The council kept the original register in safe storage and created a digital copy for the orchard archive. New entries recorded maintenance, school visits, and community contributions.", "The gardening club planted a small number of suitable new trees according to the approved plan and agreed to review their progress each term.", "Tari wrote on the final page of the club's new register: 'A tree remembers through its rings; a community remembers through the care it continues.' The orchard had a future because its history had been shared."))
            )
        )
    )
}
